def get_urls(self):
    urls = super().get_urls()
    custom_urls = [
        path('<path:object_id>/gantt/', self.admin_site.admin_view(self.gantt_chart_view), name='gantt'),
    ]
    return custom_urls + urls

def gantt_chart_view(self, request, object_id, extra_context=None):
    project = self.get_object(request, object_id)
    if not project:
        return HttpResponse("Project not found", status=404)

    gantt_json = get_project_gantt_data(project)

    context = {
        **self.admin_site.each_context(request),
        'title': f'Gantt Chart for {project.name}',
        'project': project,
        'gantt_json': gantt_json,
        'opts': self.model._meta,
        'has_permission': self.has_view_or_change_permission(request, project),
    }
    return TemplateResponse(request, "admin/management/project/gantt_chart.html", context)

@admin.display(description="Gantt Chart")
